GONE_NAMES = ["Cataphract Destrier"]  # renamed (main pack row)
GONE_FLAVOR = ["Something in the high ground changed it. Now there are two of it, and neither one is sure which came first."]
assert all(len(v) == len(CODES) for t in (NAMES, FLAVOR) for v in t.values())
def dump(path, d):
    with open(path, 'w', encoding='utf-8') as fh:
        json.dump(d, fh, ensure_ascii=False, indent=1); fh.write('\n')
for i, code in enumerate(CODES):
    path = os.path.join(ROOT, 'lang', code + '.json'); ui = os.path.join(ROOT, 'lang', 'ui', code + '.json'); cards = os.path.join(ROOT, 'lang', 'cards', code + '.json')
    pack = json.load(open(path, encoding='utf-8')); uipack = json.load(open(ui, encoding='utf-8')); cpack = json.load(open(cards, encoding='utf-8'))
    ui_sorted, c_sorted = list(uipack) == sorted(uipack), list(cpack) == sorted(cpack)
    for en in GONE_NAMES: pack.pop(en, None); cpack.pop(en, None)
    for en in GONE_FLAVOR: pack.pop(en, None); uipack.pop(en, None)
    for en, row in NAMES.items(): pack.pop(en, None); cpack[en] = row[i]
    for en, row in FLAVOR.items(): pack.pop(en, None); uipack[en] = row[i]
    dump(path, pack); dump(ui, dict(sorted(uipack.items())) if ui_sorted else uipack); dump(cards, dict(sorted(cpack.items())) if c_sorted else cpack)
print('wrote', len(CODES), 'packs:', len(NAMES), 'names,', len(FLAVOR), 'flavour lines')
